components.css:
.ds-hud-canvas{box-sizing:border-box;width:438px;height:104px;padding:20px;background:transparent;color:var(--text,#f6f6f6);font:12px/1.4 Manrope,'Segoe UI','Nirmala UI',sans-serif;user-select:none}.ds-hud-capsule{box-sizing:border-box}.ds-hud-capsule{width:100%;height:64px;display:grid;grid-template-columns:34px minmax(0,1fr) 1px 76px;align-items:center;gap:12px;padding:10px 13px 10px 17px;border:1px solid #343434;border-radius:999px;background:var(--surface,#161616);box-shadow:0 6px 15px #00000038;isolation:isolate}
.ds-hud-signal{height:30px;width:34px;display:grid;place-items:center;overflow:hidden}
.ds-hud-wave{height:28px;width:34px;display:flex;align-items:center;justify-content:center;gap:2px;overflow:hidden}
.ds-hud-wave i{display:block;width:2px;height:4px;flex-shrink:0;border-radius:2px;background:#ededed;transform:scaleY(var(--height,1));transition:transform 110ms linear;will-change:transform}
.ds-hud-wave i:nth-child(2n){background:#b3b3b3}
.ds-hud-copy{min-width:0;align-self:center}
.ds-hud-status-row{display:flex;align-items:baseline;justify-content:space-between;gap:8px;min-height:19px}
.ds-hud-status-row strong{font-size:14px;font-weight:600;letter-spacing:-.015em;white-space:nowrap}
#ds-hud-elapsed{color:#b7b7b7;font-size:11px;font-weight:500;font-variant-numeric:tabular-nums;letter-spacing:.01em}
.ds-hud-detail-row{display:flex;align-items:center;gap:9px;margin-top:4px;height:19px;min-width:0}
.ds-hud-language{display:inline-flex;align-items:center;padding:2px 7px;border-radius:999px;background:#303030;color:#e2e2e2;font-size:11px;font-weight:600;line-height:14px;white-space:nowrap;max-width:105px;overflow:hidden;text-overflow:ellipsis}
.ds-hud-key-hint{display:flex;align-items:center;gap:4px;color:#b8b8b8;font-size:11px;white-space:nowrap}
.ds-hud-key-hint kbd{font:500 10px/15px Manrope,sans-serif;min-width:15px;height:17px;display:inline-block;border:1px solid #555;border-radius:4px;text-align:center;color:#ddd}
.ds-hud-key-hint>span:last-child{margin-left:2px}
.ds-hud-note{font-size:11px;color:var(--secondary,#b8b8b8);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.ds-hud-separator{height:26px;width:1px;background:var(--hairline,#393939)}
.ds-hud-controls{display:flex;align-items:center;justify-content:flex-end;gap:6px}
.ds-hud-canvas button{display:grid;place-items:center;border:0;padding:0;cursor:pointer;border-radius:50%;flex-shrink:0;transition:background 160ms,color 160ms,transform 160ms var(--ease,cubic-bezier(.16,1,.3,1))}
.ds-hud-canvas button:active{transform:scale(.92)}
.ds-hud-canvas button:focus-visible{outline:2px solid #fff;outline-offset:3px}
.ds-hud-canvas button svg{height:20px;width:20px}
.ds-hud-primary{width:36px;height:36px;background:#f2f2f2;color:#191919}
.ds-hud-primary:hover{background:#d7d7d7}
.ds-hud-dismiss{width:30px;height:30px;background:transparent;color:#bdbdbd}
.ds-hud-dismiss:hover{color:#fff;background:#333}
.ds-hud-dismiss svg{width:18px;height:18px}
.ds-hud-spinner{display:none;width:28px;height:28px;stroke:#e4e4e4;stroke-width:1.7;stroke-linecap:round;animation:ds-hud-turn 1s linear infinite}
.ds-hud-spinner-track{stroke:#464646}
.ds-hud-signal-symbol{display:none;line-height:0}
.ds-hud-signal-symbol svg{height:24px;width:24px;stroke:#ededed;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.ds-hud-capsule[data-stage=starting] .ds-hud-wave,.ds-hud-capsule[data-stage=transcribing] .ds-hud-wave,.ds-hud-capsule[data-stage=polishing] .ds-hud-wave,.ds-hud-capsule[data-stage=inserting] .ds-hud-wave{display:none}
.ds-hud-capsule[data-stage=starting] .ds-hud-spinner,.ds-hud-capsule[data-stage=transcribing] .ds-hud-spinner,.ds-hud-capsule[data-stage=polishing] .ds-hud-spinner,.ds-hud-capsule[data-stage=inserting] .ds-hud-spinner{display:block}
.ds-hud-capsule[data-stage=done] .ds-hud-wave,.ds-hud-capsule[data-stage=error] .ds-hud-wave,.ds-hud-capsule[data-stage=cancelled] .ds-hud-wave{display:none}
.ds-hud-capsule[data-stage=done] .ds-hud-signal-symbol,.ds-hud-capsule[data-stage=error] .ds-hud-signal-symbol,.ds-hud-capsule[data-stage=cancelled] .ds-hud-signal-symbol{display:block}
.ds-hud-hidden{display:none!important}
@keyframes ds-hud-turn{to{transform:rotate(360deg)}}
@media(prefers-reduced-motion:reduce){.ds-hud-canvas *,.ds-hud-canvas *:before,.ds-hud-canvas *:after{transition:none!important;animation:none!important}}
